import {playerMail,mailUrl} from './mail-trigger-hooks.js';
import {openPlayerProgramme, renderPlayerDashboard} from './player-dashboard.js';

export function createPortal(ctx,rooms,competitions,training){
 const c=ctx,e=c.esc,I=c.icon,B=c.button;let friendFilter='all',historyFilter='all';
 function init(){c.db.play||={};rooms.init();competitions.init();training.init();if(!c.db.play.social)c.db.play.social={friends:[2,5,10,12],favorites:[2],blocked:[],reports:[]};if(!c.db.play.space){c.db.play.space='player';c.db.role='player';}c.db.play.notifications||=[];if(c.db.play.activeClubId===undefined)c.db.play.activeClubId=null;social().requests||=[{id:701,from:4,to:1,status:'pending'},{id:702,from:1,to:7,status:'pending'}];}
 const social=()=>c.db.play.social;
 const meta=m=>c.db.play.rooms?.[m.id]||{};
 const status=m=>{const x=meta(m);return x.phase==='lobby'?'In de lobby':x.phase==='paused'?'Gepauzeerd':m.status==='finished'?(x.confirmations?.every(Boolean)?'Bevestigd':'Uitslag controleren'):'Bezig';};
 const stateBadge=m=>c.badge(status(m),m.status==='finished'?'finished':meta(m).phase==='paused'?'pending':'live');
 const mode=m=>({remote:'Op afstand',localone:'Samen · één bord',localtwo:'Samen · twee borden',hybrid:'Club & thuis'}[meta(m).setup]||m.mode);
 const type=m=>({practice:'Oefenwedstrijd',ranked:'Ranked',league:'Competitie',tournament:'Toernooi'}[meta(m).type]||'Clubwedstrijd');
 const rows=(matches,limit=20)=>matches.slice(0,limit).map(m=>`<article class="dr-fixture"><div class="dr-inline">${c.avatar(m.players[0])}<div><strong>${e(c.P(m.players[0]).name)} <span class="dr-muted">vs</span> ${e(c.P(m.players[1]).name)}</strong><small>${e(type(m))} · ${e(mode(m))}</small></div></div><div class="dr-inline"><b class="dr-fixture-score">${m.legs.join(' – ')}</b>${stateBadge(m)}${B(m.status==='finished'?'Uitslag':'Open wedstrijd','open-match','small gold',`data-id="${m.id}"`)}</div></article>`).join('');
 function home(){return renderPlayerDashboard(c,rows);}
 function mymatches(){const all=c.db.matches.filter(m=>(m.players.includes(1)||meta(m).createdBy===1)&&((m.clubId??meta(m).clubId??null)===c.scopeId())).slice().reverse();const filtered=all.filter(m=>historyFilter==='all'||(historyFilter==='live'?m.status==='live':historyFilter==='finished'?m.status==='finished':meta(m).type===historyFilter));return c.header('Mijn wedstrijden','Wedstrijdkamers en uitslagen in '+e(c.scopeName())+'.',B(I('plus')+' Nieuwe wedstrijd','room-new','gold'))+`<div class="df-workspace__note"><div><strong>Via een baan-QR gespeeld?</strong><p>Open de baan met hetzelfde demoprofiel om je gedeelde Baanmodus-historie te zien.</p></div>${B('Open Baanmodus','nav-baan','ghost small')}</div><div class="toolbar"><div class="tabs">${[['all','Alle'],['live','Actief'],['finished','Afgerond'],['practice','Oefenen'],['ranked','Ranked'],['league','Competitie'],['tournament','Toernooi']].map(([id,l])=>`<button class="tab ${historyFilter===id?'active':''}" data-action="portal-history-filter" data-value="${id}">${l}</button>`).join('')}</div><span class="subtle-label">${filtered.length} wedstrijden</span></div><section class="panel">${filtered.length?rows(filtered):c.empty('Nog geen wedstrijden','Maak een partij aan of doe mee aan een competitie.','target')}</section>`;}
 function friends(){if(friendFilter==='requests')return friendRequests();const ids=c.db.players.filter(p=>p.status==='approved'&&p.id!==1).map(p=>p.id).filter(id=>friendFilter==='friends'?social().friends.includes(id)&&!social().blocked.includes(id):friendFilter==='favorites'?social().favorites.includes(id)&&!social().blocked.includes(id):friendFilter==='blocked'?social().blocked.includes(id):!social().blocked.includes(id));return c.header('Samen aan de oche. <em>Ook op afstand.</em>','Vind je vrienden, daag ze uit en spreek een revanche af.',B(I('user')+' Vriend uitnodigen','portal-invite','gold'))+`<div class="toolbar"><div class="tabs">${[['all','Clubspelers'],['friends','Mijn vrienden'],['favorites','Favorieten'],['requests','Verzoeken'],['blocked','Geblokkeerd']].map(([id,l])=>`<button class="tab ${friendFilter===id?'active':''}" data-action="portal-friend-filter" data-value="${id}">${l}</button>`).join('')}</div><div class="input-wrap">${I('search')}<input class="input" id="dr-friend-search" placeholder="Zoek een dartmaatje…" aria-label="Zoek een dartmaatje"></div></div><div class="dr-grid dr-grid-3">${ids.map((id,i)=>`<article class="panel dr-friend-card" data-friend-name="${e(c.P(id).name.toLowerCase())}"><div class="dr-inline">${c.avatar(id,'lg')}<div><h3>${e(c.P(id).name)}</h3><small class="dr-meta"><i class="dr-presence ${i%4===2?'busy':''}"></i> ${i%4===2?'In een wedstrijd':'Online · voorbeeldstatus'}</small></div></div><div class="dr-friend-metrics"><span>Gemiddelde <b>${c.P(id).avg.toFixed(1)}</b></span><span>Hoogste finish <b>${c.P(id).finish}</b></span></div><div class="dr-inline dr-wrap">${social().blocked.includes(id)?B('Deblokkeren','portal-block','ghost small',`data-id="${id}"`):`${B('Uitdagen '+I('arrow'),'room-invite-friend','gold small',`data-id="${id}"`)}${B(social().friends.includes(id)?'Vriend verwijderen':social().requests.some(r=>r.status==='pending'&&r.from===1&&r.to===id)?'Verzoek verzonden':'Vriend toevoegen','portal-friend','ghost small',`data-id="${id}"`)}`}</div><div class="dr-friend-tools"><button class="text-link" data-action="portal-favorite" data-id="${id}">${I('crown')}${social().favorites.includes(id)?'Favoriet':'Favoriet maken'}</button><button class="text-link" data-action="portal-report" data-id="${id}">Melden / blokkeren</button></div></article>`).join('')}</div>${!ids.length?c.empty('Nog even rustig hier','Je kunt clubspelers toevoegen als vriend.','users'):''}`;}
 function invite(){c.showModal('Daag iemand uit.','Kies een dartmaatje of maak een privéwedstrijd met uitnodigingscode.',`<div class="dr-friend-list">${social().friends.filter(id=>!social().blocked.includes(id)).map(id=>`<button class="search-result" data-action="room-invite-friend" data-id="${id}">${c.avatar(id)}${e(c.P(id).name)}<small>Ø ${c.P(id).avg} ${I('right')}</small></button>`).join('')}</div><div class="modal-actions">${B('Via een privécode','room-new','gold')}</div>`);}
 function overlay(){let m=c.db.matches.find(m=>m.id===c.roomId());if(!m)return c.empty('Wedstrijd niet gevonden','Open de kijkerslink vanuit een bestaande partij.');return `<div class="dr-broadcast"><div class="dr-broadcast-top"><img src="assets/dartflow-logo.svg" alt="Dartflow"><span>${e(type(m))} · ${m.startScore} · ${m.legLimit?m.legLimit+' vaste legs':'Best of '+m.bestOf}</span>${c.badge(m.status==='live'?'LIVE SCORE':'UITSLAG',m.status==='live'?'live':'finished')}</div>${m.players.map((id,i)=>`<div class="dr-broadcast-player ${m.turn===i&&m.status==='live'?'turn':''}"><span>${c.avatar(id)}${e(c.P(id).name)}</span><b>${m.legs[i]}</b><strong>${m.remaining[i]}</strong></div>`).join('')}<div class="dr-broadcast-foot">${m.status==='live'?e(c.short(m.players[m.turn]))+' aan de beurt':m.draw?'Gelijkspel':e(c.P(m.winner).name)+' wint'} · Lokale demoscore · ${B('Terug naar de kijkersmodus','nav','ghost small',`data-to="spectator/${m.id}"`)}</div></div>`;}
 function action(a,b){if(a==='portal-programme'){openPlayerProgramme(c,b.dataset.kind,Number(b.dataset.id));return true;}if(a==='portal-notifications'){notifications();return true;}if(a==='portal-requests'){friendFilter='requests';c.closeModal();c.go('friends');return true;}if(a==='portal-friend'){const id=Number(b.dataset.id);if(social().friends.includes(id)){social().friends=social().friends.filter(x=>x!==id);c.toast('Vriend verwijderd.');}else if(social().requests.some(r=>r.status==='pending'&&((r.from===1&&r.to===id)||(r.from===id&&r.to===1)))){friendFilter='requests';c.go('friends');return true;}else{const request={id:Date.now(),from:1,to:id,status:'pending'};social().requests.push(request);playerMail(c,'friend-request',`friend:${request.id}:pending`,null,id,{actorName:c.P(1).name,actionUrl:mailUrl(c,'friends')});c.toast('Vriendschapsverzoek opgeslagen in de demo.');}c.save();c.render();return true;}if(['portal-accept-friend','portal-reject-friend','portal-simulate-friend','portal-cancel-friend'].includes(a)){const r=social().requests.find(x=>x.id===Number(b.dataset.id));if(!r||r.status!=='pending')return true;r.status=['portal-accept-friend','portal-simulate-friend'].includes(a)?'approved':'rejected';const who=r.from===1?r.to:r.from;if(r.status==='approved'&&!social().friends.includes(who)&&!social().blocked.includes(who))social().friends.push(who);if(r.status==='approved')playerMail(c,'friend-accepted',`friend:${r.id}:approved`,null,r.from,{actorName:c.P(r.to).name,actionUrl:mailUrl(c,'friends')});c.save();c.render();c.toast(r.status==='approved'?'Jullie zijn nu dartvrienden.':'Het verzoek is gesloten.');return true;}if(a==='portal-resolve-report'){const r=social().reports.find(x=>x.id===Number(b.dataset.id));if(r&&!r.resolved){r.resolved=true;playerMail(c,'moderation-notice',`report:${r.id}:resolved`,null,1,{roomName:'Dartflow',reason:'Je melding is beoordeeld door de wedstrijdleiding.',status:'Melding afgehandeld',actionUrl:mailUrl(c,'reports')});}c.save();c.render();c.toast('Melding afgehandeld.');return true;}if(a==='portal-resolve-dispute'){const m=c.db.matches.find(x=>x.id===Number(b.dataset.id)),d=m&&meta(m);if(d?.dispute&&c.db.role==='admin'){d.audit.push({at:new Date().toISOString(),type:'organizer-resolution',reason:d.dispute});d.dispute=null;d.confirmations=[true,true];if(!d.finalApplied){competitions.onFinished(m);d.finalApplied=true;}for(const pid of m.players)playerMail(c,'result-resolved',`match:${m.id}:resolved:${d.audit.length}`,m.clubId,pid,{score:m.legs.join(' – '),opponentName:c.P(m.players.find(id=>id!==pid)).name,reason:'De organisator heeft de uitslag vastgesteld.',actionUrl:mailUrl(c,'match/'+m.id)});c.save();c.render();c.toast('Uitslag bevestigd door de demo-organisator.');}return true;}if(a==='portal-space'){c.db.play.space=b.dataset.space;c.db.role=b.dataset.space==='organizer'?'admin':'player';c.save();c.go(b.dataset.space==='organizer'?'dashboard':'home');return true;}if(a==='portal-invite'){invite();return true;}if(a==='portal-history-filter'){historyFilter=b.dataset.value;c.render();return true;}if(a==='portal-friend-filter'){friendFilter=b.dataset.value;c.render();return true;}if(['portal-favorite','portal-block'].includes(a)){const id=Number(b.dataset.id),key={'portal-friend':'friends','portal-favorite':'favorites','portal-block':'blocked'}[a],arr=social()[key];social()[key]=arr.includes(id)?arr.filter(x=>x!==id):[...arr,id];c.save();c.closeModal();c.render();c.toast(a==='portal-block'?'Je blokkeerlijst is bijgewerkt.':'Je dartmaatjes zijn bijgewerkt.');return true;}if(a==='portal-report'){const id=Number(b.dataset.id);c.showModal('Melden of blokkeren.',`Deze actie gaat over ${e(c.P(id).name)}.`, `<form data-form="portal-report"><input name="playerId" type="hidden" value="${id}"><label class="field">Wat is er gebeurd?<select name="reason"><option>Onjuist scoregedrag</option><option>Ongewenst contact</option><option>Technisch probleem</option><option>Anders</option></select></label><label class="field">Toelichting<input class="input" name="note" maxlength="250" placeholder="Beschrijf kort wat er gebeurde"></label><p class="subtle-label">De melding wordt alleen in deze demo opgeslagen voor de organisator.</p><div class="modal-actions">${B('Speler blokkeren','portal-block','danger',`data-id="${id}"`)}<button class="btn gold">Melding opslaan</button></div></form>`);return true;}return false;}
 function form(form,values){if(form.dataset.form==='portal-preferences'){const score=Number(values.score),bestOf=Number(values.bestOf);if([301,501,701].includes(score)&&[1,3,5,7,9].includes(bestOf)){c.db.settings.score=score;c.db.settings.bestOf=bestOf;c.save();c.toast('Je speelvoorkeuren zijn opgeslagen.');}return true;}if(form.dataset.form!=='portal-report')return false;const report={id:Date.now(),...values,date:new Date().toISOString()};social().reports.unshift(report);playerMail(c,'moderation-report',`report:${report.id}:received`,null,9,{roomName:'Dartflow',actorName:c.P(1).name,reason:report.reason+(report.note?' — '+report.note:''),actionUrl:mailUrl(c,'reports')});c.save();c.closeModal();c.toast('Je melding is opgeslagen in de demo.');return true;}
 function preferences(){const s=c.db.settings;return c.header('Voorkeuren','Kies je standaardspel en stel meldingen in.')+`<div class="settings-grid"><form class="panel" data-form="portal-preferences"><h2>Nieuwe oefenwedstrijden</h2><div class="field-row"><label class="field">Voorkeursspel<select name="score">${[301,501,701].map(n=>`<option ${s.score===n?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Best of<select name="bestOf">${[1,3,5,7,9].map(n=>`<option value="${n}" ${s.bestOf===n?'selected':''}>${n} legs</option>`).join('')}</select></label></div><p class="dr-meta">Deze instellingen vullen het formulier voor een nieuwe vrije wedstrijd in. Competities en toernooien bepalen hun eigen spelregels.</p><button class="btn gold">${I('check')} Voorkeuren opslaan</button></form><div><section class="panel"><h2>Jouw demo-ervaring</h2><div class="toggle-row"><div><strong>Demo-meldingen</strong><small>Voorbeeldactiviteiten uit je club en het platform.</small></div><button class="switch ${s.notifications?'on':''}" role="switch" aria-checked="${s.notifications}" aria-label="Demo-meldingen" data-action="toggle-setting" data-key="notifications"></button></div><div class="toggle-row"><div><strong>Animaties</strong><small>Subtiele beweging in de interface.</small></div><button class="switch ${s.motion?'on':''}" role="switch" aria-checked="${s.motion}" aria-label="Animaties" data-action="toggle-setting" data-key="motion"></button></div><div class="dr-section-gap">${B('Camera & apparaten','nav-camera','ghost small')}</div></section><section class="panel dr-section-gap"><h2>Een frisse start</h2><p class="dr-meta">Herstel alle lokale clubs, kamers, scores en verzoeken naar de voorbeeldgegevens.</p>${B(I('undo')+' Demo herstellen','reset-demo','danger small')}</section></div></div>`;}
 function friendRequests(){const pending=social().requests.filter(r=>r.status==='pending');return c.header('Jouw volgende dartmaatje.','Vriendschapsverzoeken op dit apparaat. Voeg elkaar toe en speel samen.',B('Alle vrienden','portal-friend-filter','ghost','data-value="friends"'))+`<div class="tabs"><button class="tab" data-action="portal-friend-filter" data-value="friends">Mijn vrienden</button><button class="tab active">Verzoeken (${pending.length})</button></div><div class="dr-grid dr-grid-2">${pending.map(r=>{const incoming=r.to===1,who=incoming?r.from:r.to;return `<article class="panel"><div class="dr-inline">${c.avatar(who,'lg')}<div><h3>${e(c.P(who).name)}</h3><p class="dr-meta">${incoming?'Wil jouw dartvriend worden':'Jouw uitnodiging staat klaar'}</p></div></div><div class="dr-inline dr-wrap dr-section-gap">${incoming?B('Accepteren','portal-accept-friend','gold small',`data-id="${r.id}"`)+B('Afwijzen','portal-reject-friend','ghost small',`data-id="${r.id}"`):B('Simuleer acceptatie','portal-simulate-friend','gold small',`data-id="${r.id}"`)+B('Intrekken','portal-cancel-friend','ghost small',`data-id="${r.id}"`)}</div></article>`;}).join('')}</div>${!pending.length?c.empty('Alles bijgewerkt','Je hebt geen openstaande verzoeken.','users'):''}`;}
 function notifications(){
  if(!c.db.settings.notifications){
    c.showModal('Meldingen staan uit','Zet ze aan bij je voorkeuren.',`<div class="modal-actions">${B('Voorkeuren','nav-settings','gold')}</div>`);
    return;
  }
  if(c.db.role==='admin'){
    const count=c.scopedRegistrationRequests().filter(request=>request.status==='pending').length;
    c.showModal('Werkvoorraad','Openstaande acties in '+e(c.scopeName())+'.',`
      ${count?`<div class="notification-item"><strong>${count} openstaande aanmelding${count===1?'':'en'}</strong><p>Bekijk deelnameverzoeken en nieuwe profielen voor deze omgeving.</p>${B('Aanmeldingen','nav-registrations','small gold')}</div>`:''}
      <div class="notification-item"><strong>Overzicht van je taken</strong><p>Lidmaatschap, bordoproepen en uitslagen staan in je werkvoorraad.</p>${B('Werkvoorraad openen','nav-dashboard','small ghost')}</div>`);
    return;
  }
  const requests=social().requests.filter(request=>request.status==='pending'&&request.to===1);
  c.showModal('Jouw meldingen','Verzoeken voor je demo-account.',`
    <div class="notification-item"><strong>${requests.length?`${requests.length} vriendschapsverzoek${requests.length===1?'':'en'}`:'Geen nieuwe verzoeken'}</strong>
    ${requests.length?`<p>Bekijk wie jou wil toevoegen.</p>${B('Bekijk verzoeken','portal-requests','small gold')}`:''}</div>
    <div class="notification-item"><strong>Op jouw programma</strong><p>Op Vandaag zie je je tijdvoorstellen en komende wedstrijden.</p>${B('Naar Vandaag','nav-home','small ghost')}</div>`);
 }
 function reports(){if(c.db.role!=='admin')return c.empty('De organisator beheert meldingen','Schakel naar Organiseren om de demo te bekijken.','shield');const disputes=c.db.matches.filter(m=>meta(m).dispute);return c.header('Eerlijk spel. <em>Duidelijke afspraken.</em>','Lokale voorbeeldmeldingen en betwiste uitslagen voor de organisator.')+`<div class="dr-grid dr-grid-2">${disputes.map(m=>`<article class="panel"><h3>${e(c.short(m.players[0]))} vs ${e(c.short(m.players[1]))}</h3>${c.badge('Uitslag betwist','red')}<p>${e(meta(m).dispute)}</p><div class="dr-inline dr-wrap">${B('Wedstrijd bekijken','open-match','ghost small',`data-id="${m.id}"`)}${B('Bestaande uitslag bevestigen','portal-resolve-dispute','gold small',`data-id="${m.id}"`)}</div></article>`).join('')}${social().reports.map(r=>`<article class="panel"><h3>${e(c.P(Number(r.playerId)).name)}</h3>${c.badge(r.resolved?'Afgehandeld':'Te beoordelen',r.resolved?'finished':'pending')}<p>${e(r.reason)}</p><p class="dr-meta">${e(r.note||'Geen toelichting')}</p>${r.resolved?'':B('Afhandelen','portal-resolve-report','small gold',`data-id="${r.id}"`)}</article>`).join('')}</div>${!disputes.length&&!social().reports.length?c.empty('Er zijn geen openstaande meldingen','Nieuwe demo-meldingen en betwiste uitslagen verschijnen hier.','shield'):''}`;}
 return {init,home,mymatches,friends,overlay,reports,notifications,preferences,handleAction:action,handleForm:form,rows};
}
